import { mergeConfig } from './config.mjs';

// Public tests
assert.deepEqual(mergeConfig({ mode: 'safe', retries: 3 }, { mode: 'fast' }),
  { mode: 'fast', retries: 3 });
assert.deepEqual(mergeConfig({ network: { host: 'localhost', port: 80 } }, { network: { port: 443 } }),
  { network: { host: 'localhost', port: 443 } });
assert.deepEqual(mergeConfig({ enabled: true, retries: 3 }, { enabled: false, retries: 0 }),
  { enabled: false, retries: 0 });

// Validation
for (const bad of [null, undefined, [], 5, 'x', true, new Date(), () => {}]) {
  assert.throws(() => mergeConfig(bad, {}), TypeError, `defaults ${String(bad)}`);
  assert.throws(() => mergeConfig({}, bad), TypeError, `overrides ${String(bad)}`);
}
assert.throws(() => mergeConfig(), TypeError);

// No mutation of defaults, fresh nested objects
const defaults = { a: { x: 1 }, b: 2 };
const overrides = { a: { y: 3 } };
const out = mergeConfig(defaults, overrides);
assert.deepEqual(defaults, { a: { x: 1 }, b: 2 });
assert.deepEqual(overrides, { a: { y: 3 } });
assert.notEqual(out, defaults);
assert.notEqual(out.a, defaults.a);
assert.notEqual(out.a, overrides.a);
assert.deepEqual(out, { a: { x: 1, y: 3 }, b: 2 });

// Independence across repeated calls with same defaults
const d = { n: { p: 1 } };
const r1 = mergeConfig(d, { n: { q: 2 } });
const r2 = mergeConfig(d, { n: { r: 3 } });
assert.deepEqual(r1, { n: { p: 1, q: 2 } });
assert.deepEqual(r2, { n: { p: 1, r: 3 } });
assert.deepEqual(d, { n: { p: 1 } });

// false/0/null overrides replace
assert.deepEqual(mergeConfig({ a: 1, b: 2, c: 3 }, { a: false, b: 0, c: null }),
  { a: false, b: 0, c: null });

// nested override replaces primitive default and vice versa
assert.deepEqual(mergeConfig({ a: 1 }, { a: { x: 2 } }), { a: { x: 2 } });
assert.deepEqual(mergeConfig({ a: { x: 2 } }, { a: 1 }), { a: 1 });

// inherited keys ignored
const proto = { inherited: 'no' };
const withProto = Object.create(proto);
withProto.own = 'yes';
assert.deepEqual(mergeConfig(withProto, {}), { own: 'yes' });

// __proto__ and constructor as ordinary data keys from JSON.parse
const parsedDefaults = JSON.parse('{"__proto__": {"polluted": true}, "constructor": "c"}');
const parsedOverrides = JSON.parse('{"__proto__": {"extra": 1}}');
const merged = mergeConfig(parsedDefaults, parsedOverrides);
assert.equal(Object.getPrototypeOf(merged), Object.prototype);
assert.equal({}.polluted, undefined);
assert.deepEqual(Object.getOwnPropertyDescriptor(merged, '__proto__').value,
  { polluted: true, extra: 1 });
assert.equal(merged.constructor, 'c');
assert.ok(Object.keys(merged).includes('__proto__'));

// nested __proto__ key stays data
const nestedProto = JSON.parse('{"n": {"__proto__": {"x": 1}}}');
const nm = mergeConfig(nestedProto, {});
assert.equal(Object.getPrototypeOf(nm.n), Object.prototype);
assert.deepEqual(Object.getOwnPropertyDescriptor(nm.n, '__proto__').value, { x: 1 });

console.log('ALL CHECKS PASSED');
"}

